package com.vedashree.game.admin;

import jakarta.servlet.ServletContext;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Map;

/**
 * Serves HTML from /WEB-INF (unreachable by direct URL) after replacing %%TOKENS%%. Only values
 * generated by the server (hex CSRF token, fixed messages) are substituted, never request input.
 */
final class Templates {
    private Templates() { }

    static void render(ServletContext context, HttpServletResponse resp, String path,
                       Map<String, String> tokens) throws IOException {
        String html;
        try (InputStream in = context.getResourceAsStream(path)) {
            if (in == null) {
                resp.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
                resp.setContentType("text/plain");
                resp.getWriter().write("Template missing.");
                return;
            }
            html = new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
        for (Map.Entry<String, String> token : tokens.entrySet()) {
            html = html.replace("%%" + token.getKey() + "%%", token.getValue());
        }
        resp.setStatus(HttpServletResponse.SC_OK);
        resp.setContentType("text/html");
        resp.setCharacterEncoding("UTF-8");
        resp.setHeader("Cache-Control", "no-store");
        resp.getWriter().write(html);
    }
}
